    "content": "<main class=\"data-grid\">\n<div class=\"data-grid-header\">\n<!-- Division selector (mobile) -->\n\n<!-- Header title -->\n<div class=\"header-title\"></div>\n<div class=\"search-and-sort-container\">\n<!-- Search -->\n<div class=\"cmp-brand-input input-group\" id=\"grid-search\">\n<input autocomplete=\"off\" class=\"form-control border-end-0\" placeholder=\"Find product by title\" type=\"text\"/>\n<div class=\"input-right border-start-0 rounded-start-0\">\n\n<div class=\"vertical-divide\"></div>\n\n</div>\n</div>\n<div class=\"sort-container\">\n<div>Sort by:</div>\n<!-- Sort dropdown -->\n<div class=\"sort-select\">\n<select class=\"form-select form-select-primary fw-bold\">\n<option selected=\"\" value=\"relevance\">Relevance</option>\n<option value=\"asc\">Alphabetical A → Z</option>\n<option value=\"desc\">Alphabetical Z → A</option>\n<option value=\"dateAsc\">Last modified ↑ (Oldest first)</option>\n<option value=\"dateDesc\">Last modified ↓ (Newest first)</option>\n</select>\n</div>\n</div>\n</div>\n</div>\n<!-- Responsive grid -->\n<div class=\"card-grid row g-3\"></div>\n<!-- Pagination -->\n<div class=\"pagination-container\">\n<ul class=\"pagination\"></ul>\n<div class=\"page-size-container\">\n<div class=\"page-size-container-label\">Results per page:</div>\n<div class=\"page-size-select\">\n<select class=\"form-select form-select-primary fw-bold\">\n<option selected=\"\" value=\"12\">12</option>\n<option value=\"24\">24</option>\n<option value=\"48\">48</option>\n</select>\n</div>\n</div>\n</div>\n</main>",
