        "label": "Backup and Restore VCF Management Services in vSphere Foundation",
        "url": "https://techdocs.broadcom.com/us/en/vmware-cis/vcf/vcf-9-0-and-later/9-1/fleet-management/backup-and-restore-of-cloud-foundation/deleting-vcf-components-post-deployment.html"
